/** Complete purple flavor. Use this file as the theme entry point. */
@import url('./cyberpunk-midnight.css');

body {
    /* Every option is surfaced; unchanged values inherit Cyberpunk. */
    --flavor-font: var(--cyber-font); /* change to '' for default discord font */
    --flavor-code-font: var(--cyber-code-font); /* change to '' for default discord font */
    --flavor-gap: var(--cyber-gap); /* spacing between panels */
    --flavor-divider-thickness: var(--cyber-divider-thickness); /* thickness of unread messages divider and highlighted message borders */
    --flavor-border-thickness: var(--cyber-border-thickness); /* thickness of borders around main panels. DOES NOT AFFECT OTHER BORDERS */
    --flavor-animations: var(--cyber-animations); /* off: disable animations/transitions, on: enable animations/transitions */
    --flavor-list-item-transition: var(--cyber-list-item-transition); /* transition for list items */
    --flavor-dms-icon-svg-transition: var(--cyber-dms-icon-svg-transition); /* transition for the dms icon */
    --flavor-border-hover-transition: var(--cyber-border-hover-transition); /* transition for borders when hovered */
    --flavor-top-bar-height: var(--cyber-top-bar-height); /* height of the top bar (discord default is 36px, old discord style is 24px, var(--gap) recommended if button position is set to titlebar) */
    --flavor-top-bar-button-position: var(--cyber-top-bar-button-position); /* off: default position, hide: hide buttons completely, serverlist: move inbox button to server list, titlebar: move inbox button to channel titlebar (will hide title) */
    --flavor-top-bar-title-position: var(--cyber-top-bar-title-position); /* off: default centered position, hide: hide title completely, left: left align title (like old discord) */
    --flavor-subtle-top-bar-title: var(--cyber-subtle-top-bar-title); /* off: default, on: hide the icon and use subtle text color (like old discord) */
    --flavor-custom-window-controls: var(--cyber-custom-window-controls); /* off: default window controls, on: custom window controls */
    --flavor-window-control-size: var(--cyber-window-control-size); /* size of custom window controls */
    --flavor-custom-dms-icon: var(--cyber-custom-dms-icon); /* off: use default discord icon, hide: remove icon entirely, custom: use custom icon */
    --flavor-dms-icon-svg-url: var(--cyber-dms-icon-svg-url); /* icon svg url. MUST BE A SVG. */
    --flavor-dms-icon-svg-size: var(--cyber-dms-icon-svg-size); /* size of the svg (css mask-size property) */
    --flavor-dms-icon-color-before: var(--cyber-dms-icon-color-before); /* normal icon color */
    --flavor-dms-icon-color-after: var(--cyber-dms-icon-color-after); /* icon color when button is hovered/selected */
    --flavor-custom-dms-background: var(--cyber-custom-dms-background); /* off to disable, image to use a background image (must set url variable below), color to use a custom color/gradient */
    --flavor-dms-background-image-url: var(--cyber-dms-background-image-url); /* url of the background image */
    --flavor-dms-background-image-size: var(--cyber-dms-background-image-size); /* size of the background image (css background-size property) */
    --flavor-dms-background-color: var(--cyber-dms-background-color); /* fixed color/gradient (css background property) */
    --flavor-background-image: var(--cyber-background-image); /* off: no background image, on: enable background image (must set url variable below) */
    --flavor-background-image-url: url('data:image/jpeg;base64,'); /* url of the background image */
    --flavor-transparency-tweaks: var(--cyber-transparency-tweaks); /* off: no changes, on: remove some elements for better transparency */
    --flavor-remove-bg-layer: var(--cyber-remove-bg-layer); /* off: no changes, on: remove the base --bg-3 layer for use with window transparency (WILL OVERRIDE BACKGROUND IMAGE) */
    --flavor-panel-blur: var(--cyber-panel-blur); /* off: no changes, on: blur the background of panels */
    --flavor-blur-amount: var(--cyber-blur-amount); /* amount of blur */
    --flavor-bg-floating: var(--cyber-bg-floating); /* set this to a more opaque color if floating panels look too transparent. only applies if panel blur is on */
    --flavor-custom-chatbar: var(--cyber-custom-chatbar); /* off: default chatbar, separated: chatbar separated from chat */
    --flavor-chatbar-height: var(--cyber-chatbar-height); /* height of the chatbar (56px by default, 47px to align with user panel, 56px recommended for separated) */
    --flavor-small-user-panel: var(--cyber-small-user-panel); /* off: default user panel, on: smaller user panel like in old discord */
    --flavor-font-weight: var(--cyber-font-weight);
    /* Final effective Midnight options */
    --font: var(--flavor-font);
    --code-font: var(--flavor-code-font);
    --gap: var(--flavor-gap);
    --divider-thickness: var(--flavor-divider-thickness);
    --border-thickness: var(--flavor-border-thickness);
    --animations: var(--flavor-animations);
    --list-item-transition: var(--flavor-list-item-transition);
    --dms-icon-svg-transition: var(--flavor-dms-icon-svg-transition);
    --border-hover-transition: var(--flavor-border-hover-transition);
    --top-bar-height: var(--flavor-top-bar-height);
    --top-bar-button-position: var(--flavor-top-bar-button-position);
    --top-bar-title-position: var(--flavor-top-bar-title-position);
    --subtle-top-bar-title: var(--flavor-subtle-top-bar-title);
    --custom-window-controls: var(--flavor-custom-window-controls);
    --window-control-size: var(--flavor-window-control-size);
    --custom-dms-icon: var(--flavor-custom-dms-icon);
    --dms-icon-svg-url: var(--flavor-dms-icon-svg-url);
    --dms-icon-svg-size: var(--flavor-dms-icon-svg-size);
    --dms-icon-color-before: var(--flavor-dms-icon-color-before);
    --dms-icon-color-after: var(--flavor-dms-icon-color-after);
    --custom-dms-background: var(--flavor-custom-dms-background);
    --dms-background-image-url: var(--flavor-dms-background-image-url);
    --dms-background-image-size: var(--flavor-dms-background-image-size);
    --dms-background-color: var(--flavor-dms-background-color);
    --background-image: var(--flavor-background-image);
    --background-image-url: var(--flavor-background-image-url);
    --transparency-tweaks: var(--flavor-transparency-tweaks);
    --remove-bg-layer: var(--flavor-remove-bg-layer);
    --panel-blur: var(--flavor-panel-blur);
    --blur-amount: var(--flavor-blur-amount);
    --bg-floating: var(--flavor-bg-floating);
    --custom-chatbar: var(--flavor-custom-chatbar);
    --chatbar-height: var(--flavor-chatbar-height);
    --small-user-panel: var(--flavor-small-user-panel);
    font-weight: var(--flavor-font-weight);
}

