    --flavor-bg-1: var(--cyber-bg-1);
    --flavor-bg-2: var(--cyber-bg-2);
    --flavor-bg-3: var(--cyber-bg-3);
    --flavor-bg-4: var(--cyber-bg-4);
    --flavor-hover: var(--cyber-hover);
