    --flavor-dnd: var(--cyber-dnd);
    --flavor-idle: var(--cyber-idle);
    --flavor-streaming: var(--cyber-streaming);
    --flavor-offline: var(--cyber-offline);
    --flavor-border-light: var(--cyber-border-light);
    --flavor-border: var(--cyber-border);
    --flavor-border-hover: var(--cyber-border-hover);
    --flavor-button-border: var(--cyber-button-border);
    --flavor-red-1: var(--cyber-red-1);
    --flavor-red-2: var(--cyber-red-2);
    --flavor-red-3: var(--cyber-red-3);
    --flavor-red-4: var(--cyber-red-4);
    --flavor-red-5: var(--cyber-red-5);
    --flavor-green-1: var(--cyber-green-1);
