    --flavor-green-3: var(--cyber-green-3);
    --flavor-green-4: var(--cyber-green-4);
    --flavor-green-5: var(--cyber-green-5);
    --flavor-blue-1: var(--cyber-blue-1);
    --flavor-blue-2: var(--cyber-blue-2);
    --flavor-blue-3: var(--cyber-blue-3);
    --flavor-blue-4: var(--cyber-blue-4);
    --flavor-blue-5: var(--cyber-blue-5);
    --flavor-yellow-1: var(--cyber-yellow-1);
