    --flavor-yellow-3: var(--cyber-yellow-3);
    --flavor-yellow-4: var(--cyber-yellow-4);
    --flavor-yellow-5: var(--cyber-yellow-5);
    --flavor-purple-1: var(--cyber-purple-1);
    --flavor-purple-2: var(--cyber-purple-2);
    --flavor-purple-3: var(--cyber-purple-3);
    --flavor-purple-4: var(--cyber-purple-4);
    --flavor-purple-5: var(--cyber-purple-5);

    /* Purple flavor overrides: complete Midnight palette */
    --flavor-colors: on;
    --flavor-text-0: hsl(270, 35%, 8%);
    --flavor-text-1: hsl(280, 40%, 97%);
    --flavor-text-2: hsl(280, 30%, 90%);
    --flavor-text-3: hsl(280, 20%, 76%);
    --flavor-text-4: hsl(280, 15%, 58%);
    --flavor-text-5: hsl(280, 12%, 42%);
    --flavor-bg-1: hsla(276, 45%, 20%, 0.72);
    --flavor-bg-2: hsla(274, 42%, 15%, 0.72);
    --flavor-bg-3: hsla(272, 40%, 10%, 0.70);
    --flavor-bg-4: hsla(270, 45%, 6%, 0.68);
    --flavor-hover: hsla(287, 90%, 70%, 0.10);
    --flavor-active: hsla(287, 90%, 70%, 0.18);
    --flavor-active-2: hsla(287, 90%, 70%, 0.28);
    --flavor-message-hover: hsla(290, 80%, 40%, 0.08);
    --flavor-accent-1: hsl(292, 100%, 82%);
    --flavor-accent-2: hsl(294, 95%, 70%);
    --flavor-accent-3: hsl(296, 85%, 59%);
    --flavor-accent-4: hsl(302, 90%, 65%);
    --flavor-accent-5: hsl(310, 85%, 54%);
    --flavor-accent-new: hsl(326, 95%, 65%);
    --flavor-mention: linear-gradient( to right, hsla(296, 95%, 65%, 0.18) 40%, transparent );
    --flavor-mention-hover: linear-gradient( to right, hsla(296, 95%, 65%, 0.10) 40%, transparent );
    --flavor-reply: linear-gradient( to right, hsla(272, 85%, 78%, 0.14) 40%, transparent );
    --flavor-reply-hover: linear-gradient( to right, hsla(272, 85%, 78%, 0.08) 40%, transparent );
    --flavor-online: hsl(160, 65%, 62%);
    --flavor-dnd: hsl(342, 90%, 65%);
    --flavor-idle: hsl(42, 90%, 68%);
    --flavor-streaming: hsl(286, 90%, 68%);
    --flavor-offline: var(--text-4);
    --flavor-border-light: hsla(292, 90%, 75%, 0.10);
    --flavor-border: hsla(292, 90%, 75%, 0.18);
    --flavor-border-hover: hsla(302, 95%, 72%, 0.35);
    --flavor-button-border: hsla(292, 100%, 92%, 0.12);
    --flavor-red-1: hsl(345, 95%, 78%);
    --flavor-red-2: hsl(345, 90%, 70%);
    --flavor-red-3: hsl(345, 85%, 63%);
    --flavor-red-4: hsl(345, 80%, 56%);
    --flavor-red-5: hsl(345, 75%, 49%);
    --flavor-green-1: hsl(160, 75%, 75%);
    --flavor-green-2: hsl(160, 65%, 62%);
    --flavor-green-3: hsl(160, 60%, 55%);
    --flavor-green-4: hsl(160, 55%, 48%);
    --flavor-green-5: hsl(160, 50%, 41%);
    --flavor-blue-1: hsl(256, 100%, 82%);
    --flavor-blue-2: hsl(258, 95%, 74%);
    --flavor-blue-3: hsl(261, 90%, 66%);
    --flavor-blue-4: hsl(265, 80%, 59%);
    --flavor-blue-5: hsl(268, 75%, 52%);
    --flavor-yellow-1: hsl(45, 95%, 80%);
    --flavor-yellow-2: hsl(43, 90%, 70%);
    --flavor-yellow-3: hsl(41, 85%, 62%);
    --flavor-yellow-4: hsl(39, 80%, 55%);
    --flavor-yellow-5: hsl(37, 75%, 48%);
    --flavor-purple-1: hsl(286, 100%, 84%);
    --flavor-purple-2: hsl(288, 95%, 74%);
    --flavor-purple-3: hsl(292, 90%, 65%);
    --flavor-purple-4: hsl(297, 85%, 57%);
    --flavor-purple-5: hsl(304, 80%, 50%);

    /* Final effective Midnight colors */
    --colors: var(--flavor-colors);
    --text-0: var(--flavor-text-0);
    --text-1: var(--flavor-text-1);
    --text-2: var(--flavor-text-2);
    --text-3: var(--flavor-text-3);
    --text-4: var(--flavor-text-4);
    --text-5: var(--flavor-text-5);
    --bg-1: var(--flavor-bg-1);
    --bg-2: var(--flavor-bg-2);
    --bg-3: var(--flavor-bg-3);
    --bg-4: var(--flavor-bg-4);
    --hover: var(--flavor-hover);
    --active: var(--flavor-active);
    --active-2: var(--flavor-active-2);
    --message-hover: var(--flavor-message-hover);
    --accent-1: var(--flavor-accent-1);
    --accent-2: var(--flavor-accent-2);
    --accent-3: var(--flavor-accent-3);
    --accent-4: var(--flavor-accent-4);
    --accent-5: var(--flavor-accent-5);
    --accent-new: var(--flavor-accent-new);
    --mention: var(--flavor-mention);
    --mention-hover: var(--flavor-mention-hover);
    --reply: var(--flavor-reply);
    --reply-hover: var(--flavor-reply-hover);
    --online: var(--flavor-online);
    --dnd: var(--flavor-dnd);
    --idle: var(--flavor-idle);
    --streaming: var(--flavor-streaming);
    --offline: var(--flavor-offline);
    --border-light: var(--flavor-border-light);
    --border: var(--flavor-border);
    --border-hover: var(--flavor-border-hover);
    --button-border: var(--flavor-button-border);
    --red-1: var(--flavor-red-1);
    --red-2: var(--flavor-red-2);
    --red-3: var(--flavor-red-3);
    --red-4: var(--flavor-red-4);
    --red-5: var(--flavor-red-5);
    --green-1: var(--flavor-green-1);
    --green-2: var(--flavor-green-2);
    --green-3: var(--flavor-green-3);
    --green-4: var(--flavor-green-4);
    --green-5: var(--flavor-green-5);
    --blue-1: var(--flavor-blue-1);
    --blue-2: var(--flavor-blue-2);
    --blue-3: var(--flavor-blue-3);
    --blue-4: var(--flavor-blue-4);
    --blue-5: var(--flavor-blue-5);
    --yellow-1: var(--flavor-yellow-1);
    --yellow-2: var(--flavor-yellow-2);
    --yellow-3: var(--flavor-yellow-3);
    --yellow-4: var(--flavor-yellow-4);
    --yellow-5: var(--flavor-yellow-5);
    --purple-1: var(--flavor-purple-1);
    --purple-2: var(--flavor-purple-2);
    --purple-3: var(--flavor-purple-3);
    --purple-4: var(--flavor-purple-4);
    --purple-5: var(--flavor-purple-5);

    /* Purple Cyberpunk animation palette */
    --cyber-dms-gradient: linear-gradient(
        135deg,
        hsl(258, 42%, 17%),
        hsl(278, 48%, 13%),
        hsl(304, 42%, 15%),
        hsl(258, 42%, 17%)
    );
    --cyber-dms-gradient-size: 300% 300%;
    --cyber-dms-icon-start: hsl(185, 85%, 82%);
    --cyber-dms-icon-mid: hsl(315, 85%, 82%);
    --cyber-dms-glow-start-1: hsla(185, 100%, 85%, 0.75);
    --cyber-dms-glow-start-2: hsla(270, 100%, 75%, 0.45);
    --cyber-dms-glow-mid-1: hsla(315, 100%, 88%, 0.85);
    --cyber-dms-glow-mid-2: hsla(295, 100%, 70%, 0.65);
    --cyber-dms-glow-mid-3: hsla(265, 100%, 65%, 0.35);
    --cyber-dms-gradient-duration: 10s;
    --cyber-dms-icon-duration: 5s;
    --cyber-dms-hover-duration: 2s;
    --cyber-dms-icon-scale: 1.05;
}
